    assert safe_div(10, 2) == 5.0
    passed += 1
except AssertionError:
    pass

try:
    assert safe_div(-10, -2) == 5.0
    passed += 1
except AssertionError:
    pass

try:
    assert safe_div(0, 1) == 0.0
    passed += 1
except AssertionError:
    pass

try:
    assert safe_div(10, 0) is None
    passed += 1
except AssertionError:
    pass

